  'festival': -17.7,
  'festival-blossom': -20.7,
  'festival-harvest': -21.3,
  'festival-starfall': -23.4,
  'festival-tide': -18.4,
  'forest': -22.7,
  'forest-2': -24.1,
  'inn': -23.6,
  'mine': -28.8,
  'mine-ice': -23.3,
  'mine-lava': -28.4,
  'night': -25.8,
  'night-fall': -22,
  'night-spring': -23.9,
  'night-summer': -24.1,
