  'summer-2': [-8.8, -9.8],
  'summer-3': [-0.9, -6.6],
  'title': [-10.4, -8.6],
  'town': [-6.3, -9.2],
  'town-2': [0, -7.6],
  'town-3': [-5.2, -9.5],
  'town-winter': [-7.9, -7.3],
  'winter': [-8.6, -9.1],
